  function persist() { localStorage.setItem("bm", JSON.stringify(bookmarks)); }

  function allTopics() { return [...new Set(bookmarks.map(b => b.topic || "Untitled topic"))].sort((a, b) => a.localeCompare(b)); }
  function renderChips() {
    const c = document.getElementById("chips");
    c.innerHTML = "";
    if (bookmarks.length === 0) return;
    if (activeTopic !== "All" && !allTopics().includes(activeTopic)) activeTopic = "All";
    ["All", ...allTopics()].forEach(t => {
      const el = document.createElement("button");
      el.className = "chip" + (t === activeTopic ? " active" : "");
      el.textContent = t;
      el.onclick = () => {
        activeTopic = t;
        if (t === "All") document.getElementById("search").value = "";
        renderChips();
        render();
      };
      c.appendChild(el);
    });
  }

  function render(flashId) {
    const list = document.getElementById("list");
    const meta = document.getElementById("search-meta");
    const q = document.getElementById("search").value.trim().toLowerCase();
    list.innerHTML = "";
    if (bookmarks.length === 0) {
      list.innerHTML = '<div class="empty">No links saved yet.<br>Add your first one above.</div>';
      meta.textContent = "";
      return;
    }
    let matches = bookmarks.map((b, i) => ({ ...b, i }));
    if (activeTopic !== "All") {
      matches = matches.filter(b => (b.topic || "Untitled topic") === activeTopic);
    }
    if (q) {
      matches = matches.filter(b =>
        (b.title || "").toLowerCase().includes(q) ||
        (b.url || "").toLowerCase().includes(q) ||
        (b.topic || "").toLowerCase().includes(q));
      meta.textContent = matches.length + (matches.length === 1 ? " link found" : " links found");
    } else {
      meta.textContent = "";
    }
    if (q && matches.length === 0) {
      list.innerHTML = '<div class="empty">No links match "' + escapeHtml(q) + '".<br>Try a different word.</div>';
      return;
    }
    const topics = {};
    matches.forEach(b => { (topics[b.topic || "Untitled topic"] ||= []).push(b); });
    Object.keys(topics).sort((a, b) => a.localeCompare(b)).forEach(topic => {
      const group = document.createElement("div");
      group.className = "topic-group";
      group.innerHTML = `<h2 class="topic-head">${escapeHtml(topic)} <span class="topic-count">${topics[topic].length}</span></h2>`;
      topics[topic].forEach(b => {
        const el = document.createElement("div");
        el.className = "bm" + (b.i === flashId ? " flash" : "");
        if (b.i === editingId) {
          renderEditForm(el, b);
        } else if (b.i === confirmingDeleteId) {
          renderDeleteConfirm(el, b);
        } else {
          el.innerHTML = `<div class="bm-main">
              <a href="${escapeAttr(b.url)}" target="_blank" rel="noopener">${highlight(b.title || b.url, q)}</a>
              <div class="url">${highlight(b.url, q)}</div>
            </div>
            <div class="bm-actions">
              <button class="edit-btn">Edit</button>
              <button class="del-btn">Delete</button>
            </div>`;
          el.querySelector(".edit-btn").onclick = () => { editingId = b.i; confirmingDeleteId = null; render(); };
          el.querySelector(".del-btn").onclick = () => { confirmingDeleteId = b.i; editingId = null; render(); };
        }
        group.appendChild(el);
      });
      list.appendChild(group);
    });
  }

